function LifXXLAiPlayerCharacter::releaseRuntime(%this)
{
    // Keep Player and both client links intact while GameConnection destroys
    // CharacterInfo. stopSim() must still be able to resolve the loaded Player.
    if (isObject(%this.connection))
    {
        %connection = %this.connection;
        %this.connection = 0;
        %connection.lifxxlAiPlayerLoader = 0;
        if (%connection.schDataLoaded !$= "")
        {
            cancel(%connection.schDataLoaded);
            %connection.schDataLoaded = "";
        }
        if (!%connection.LifXXL_beginAiPlayerConnectionRelease())
        {
            error("LifXXLAiPlayer: cannot enter native release scope for objectId" SPC
                %this.connectionObjectId @ ".");
        }
        %connection.unregisterByCharacter();
        %connection.delete();
    }
    if (%this.connectionObjectId > 0)
    {
        if (!LifXXL_unregisterAiPlayerConnection(%this.connectionObjectId))
        {
            error("LifXXLAiPlayer: native connection release failed for objectId" SPC
                %this.connectionObjectId @ ".");
        }
        %this.connectionObjectId = 0;
    }
    if (isObject(%this.actor))
    {
        if (isMethod(Player, setReferencedClient))
        {
            %this.actor.setReferencedClient(0);
        }
        %this.actor.client = 0;
        %this.actor.delete();
        %this.actor = 0;
    }
}

