void ReleaseRejectedNetEvent(LPVOID event)
{
    auto* refCount = reinterpret_cast<volatile LONG*>(
        static_cast<std::uint8_t*>(event)
        + kNetEventRefCountOffset);
    InterlockedIncrement(refCount);
    const LONG previous = InterlockedExchangeAdd(refCount, -1);
    if (previous == 1)
    {
        auto** vtable = *reinterpret_cast<LPVOID**>(event);
        reinterpret_cast<DeleteNetEventFn>(vtable[1])(event);
    }
}

bool __fastcall OnPostNetEvent(LPVOID connection, LPVOID event)
{
    // Event interface this is GameConnection + 0x1F8; console
    // commands receive the complete SimObject. Compare exact
    // registered ownership without dereferencing another connection.
    const auto object = reinterpret_cast<LPVOID>(
        reinterpret_cast<std::uintptr_t>(connection) - kGameConnectionBaseOffset);
    SyntheticConnection* slot = FindByConnection(object);
    if (slot == nullptr)
        return gPostNetEvent(connection, event);
    if (event == nullptr)
        return gPostNetEvent(connection, event);

    slot->droppedEvents.fetch_add(1, std::memory_order_relaxed);
    ReleaseRejectedNetEvent(event);
    return false;
}

void __fastcall OnSendDisconnectPacket(
    LPVOID netInterface,
    LPVOID address,
    const char* reason)
{
    // Native second argument is the full connection, not NetAddress.
    SyntheticConnection* slot = FindByConnection(address);
    if (slot != nullptr)
    {
        slot->suppressedDisconnectPackets.fetch_add(
            1,
            std::memory_order_relaxed);
        return;
    }
    gSendDisconnectPacket(netInterface, address, reason);
}

void __fastcall OnNotifyDisconnect(LPVOID manager, U32 characterId)
{
    SyntheticConnection* slot = gReleaseScope.slot;
    if (slot != nullptr
        && gReleaseScope.characterId == characterId
        && slot->connection.load(std::memory_order_acquire)
            == gReleaseScope.connection
        && slot->objectId.load(std::memory_order_acquire)
            == gReleaseScope.objectId
        && slot->characterId.load(std::memory_order_acquire)
            == characterId)
    {
        slot->suppressedPlayerNotifications.fetch_add(
            1,
            std::memory_order_relaxed);
        return;
    }
    gNotifyDisconnect(manager, characterId);

bool BindAiActor(LPVOID connection, S32 argc, const char* argv[])
{
    auto* slot = FindByConnection(connection);
    U32 actorId = 0;
    if (!slot || argc != 3 || !ParseU32(argv[2], actorId)) return false;
    const auto base = reinterpret_cast<std::uintptr_t>(GetModuleHandleW(nullptr));
    auto* actor = reinterpret_cast<FindObjectFn>(base + 0x428D00)(argv[2]);
    if (!actor || *reinterpret_cast<std::uintptr_t*>(static_cast<unsigned char*>(actor) + 0x128) != base + 0x75CC20)
        return false;
    if (slot->actor == actor && slot->actorId == actorId) return true;
    // A server-local owner must keep its Player alive independently
    // of real clients. LiF deletes a Player when the last remote ghost
    // releases GID usage. Stock explicit CharacterInfo/Player teardown
    // still destroys the object; this embedded counter owns no heap
    // resource and dies with it. Never balance it via decreaseGIDusage
    // during teardown: reaching zero would recursively delete Player.
    using IncreaseGidUsageFn = void (__fastcall*)(LPVOID, const char*);
    reinterpret_cast<IncreaseGidUsageFn>(base + 0x54A200)(
        actor, "LifXXLAiPlayer server-local owner");
    slot->actor = actor;
    slot->actorId = actorId;
    slot->moveX = slot->moveY = 0;
    slot->controls = {};
    slot->harnessTicks = slot->processTicks = slot->processVisits = 0;
    gActorPointerMask |= ConnectionPointerBit(actor);
    return true;

