void TickOne(SyntheticConnection& slot)
{
    const auto base = reinterpret_cast<std::uintptr_t>(GetModuleHandleW(nullptr));
    alignas(16) std::array<unsigned char, 96> move{};
    std::memcpy(move.data(), reinterpret_cast<const void*>(base + 0xACD410), move.size());
    AiControlInput::Apply(move.data(),slot.controls);
    reinterpret_cast<PlayerTickFn>(base + 0xFF5A0)(
        static_cast<unsigned char*>(slot.actor) + 0x128, move.data(), true);
}

void __fastcall OnProcessObject(LPVOID list, LPVOID processObject)
{
    const auto actor = reinterpret_cast<LPVOID>(reinterpret_cast<std::uintptr_t>(processObject) - 0x128);
    if (gActorPointerMask & ConnectionPointerBit(actor))
    {
        for (auto& slot : gSyntheticConnections)
        {
            if (slot.actor != actor || !slot.connection.load(std::memory_order_acquire)) continue;
            ++slot.processVisits;
            // This branch only supplies synthetic input. The stock ProcessList
            // decides ordering, cadence and catch-up. No extra timer in mode 2.
            // Real players and every other ProcessObject use the original path.
            if (gAiTickMode == 2 && *(static_cast<unsigned char*>(processObject) + 0x20))
            {
                TickOne(slot);
                ++slot.processTicks;
            }
            return;
        }
    }
    gProcessObject(list, processObject);
}

